import java.util.*;

class Solution {
  public long maxArea(int[][] coords) {
    // smallest / largest x on each row y, and smallest / largest y on each column x
    Map<Integer, int[]> rows = new HashMap<>(), cols = new HashMap<>();
    int minX = Integer.MAX_VALUE, maxX = Integer.MIN_VALUE, minY = Integer.MAX_VALUE, maxY = Integer.MIN_VALUE;
    for (int[] c : coords) {
      int x = c[0], y = c[1];
      int[] row = rows.computeIfAbsent(y, key -> new int[] {x, x});
      row[0] = Math.min(row[0], x);
      row[1] = Math.max(row[1], x);
      int[] col = cols.computeIfAbsent(x, key -> new int[] {y, y});
      col[0] = Math.min(col[0], y);
      col[1] = Math.max(col[1], y);
      minX = Math.min(minX, x);
      maxX = Math.max(maxX, x);
      minY = Math.min(minY, y);
      maxY = Math.max(maxY, y);
    }
    long best = -1;
    // a side parallel to an axis is the base; the farthest point from that line is the apex
    for (Map.Entry<Integer, int[]> e : rows.entrySet()) {
      long base = e.getValue()[1] - e.getValue()[0];
      long height = Math.max(e.getKey() - minY, maxY - e.getKey());
      if (base > 0 && height > 0) best = Math.max(best, base * height);
    }
    for (Map.Entry<Integer, int[]> e : cols.entrySet()) {
      long base = e.getValue()[1] - e.getValue()[0];
      long height = Math.max(e.getKey() - minX, maxX - e.getKey());
      if (base > 0 && height > 0) best = Math.max(best, base * height);
    }
    return best;
  }
}
